prologue:
/* Shaders the mod made, kept by the name the sheet gave them. A pair is a vertex shader and a
   pixel shader, and either half may be one of the game's built-in ones */
enum { kShaders = 8, kShaderNameLen = 32 };
static char g_shader_named[kShaders][kShaderNameLen];
static uint32_t g_shader_id[kShaders];
static int g_shader_is_pixel[kShaders];

static MOD_UNUSED int shader_slot(const char* name, int pixel, int make) {
    int at, free_slot = -1;
    if (name == 0 || name[0] == 0) return -1;
    for (at = 0; at < kShaders; ++at) {
        if (g_shader_named[at][0] == 0) {
            if (free_slot < 0) free_slot = at;
            continue;
        }
        if (g_shader_is_pixel[at] == pixel && strcmp(g_shader_named[at], name) == 0) return at;
    }
    if (make == 0 || free_slot < 0 || strlen(name) >= kShaderNameLen) return -1;
    strcpy(g_shader_named[free_slot], name);
    g_shader_is_pixel[free_slot] = pixel;
    g_shader_id[free_slot] = AMOD_INVALID_SHADER;
    return free_slot;
}

static MOD_UNUSED uint32_t shader_of(const char* name, int pixel) {
    const int slot = shader_slot(name, pixel, 0);
    return slot >= 0 ? g_shader_id[slot] : AMOD_INVALID_SHADER;
}

static MOD_UNUSED void shader_remember(const char* name, int pixel, uint32_t id) {
    const int slot = shader_slot(name, pixel, 1);
    if (slot >= 0) g_shader_id[slot] = id;
}

/* The declaration a vertex shader of the basic kind wants: position, colour and one texture
   coordinate, which is exactly what the shapes below hand over */
/* Exactly the stream the loader's own basic shader is built against: position, normal,
   colour and one texture coordinate. A declaration that does not match what DrawTriangles
   hands over is read past its end, and the game goes down with it */
static const uint32_t g_shader_declaration[] = {
    0x20000000u,   /* stream 0 */
    0x40020000u,   /* v0  float3  position */
    0x40020001u,   /* v1  float3  normal */
    0x40040002u,   /* v2  d3dcolor colour */
    0x40010003u,   /* v3  float2  texture 0 */
    0xFFFFFFFFu
};

/* A shader is written line by line, and a field of a sheet holds no line breaks: the text
   comes in with ';' between the instructions and is laid out again here */
static MOD_UNUSED const char* shader_lines(const char* source) {
    static char out[1024];
    int at = 0;
    if (source == 0) return "";
    while (source[at] != 0 && at < (int)sizeof out - 1) {
        out[at] = source[at] == ';' ? '\n' : source[at];
        ++at;
    }
    out[at] = 0;
    return out;
}

static MOD_UNUSED void shader_make_vertex(const char* name, const char* source) {
    if (API->shader == 0) return;
    shader_remember(name, 0,
                    API->shader->CreateVertexSource(SELF, shader_lines(source), g_shader_declaration));
}

static MOD_UNUSED void shader_make_pixel(const char* name, const char* source) {
    if (API->shader == 0) return;
    shader_remember(name, 1, API->shader->CreatePixelSource(SELF, shader_lines(source)));
}

/* One of the game's own: 0 the basic vertex shader, 1 texture times colour, 2 colour alone */
static MOD_UNUSED void shader_take_builtin(const char* name, int which, int pixel) {
    if (API->shader == 0) return;
    if (pixel) shader_remember(name, 1, API->shader->BuiltinPixel(SELF, (AmodBuiltinShader)which));
    else shader_remember(name, 0, API->shader->BuiltinVertex(SELF, (AmodBuiltinShader)which));
}

/* A shader that was compiled elsewhere arrives as a list of numbers, the way a tool prints it:
   "0xFFFE0101 0x00000051 ...". Anything that is not a number is a separator */
static MOD_UNUSED int shader_tokens(const char* text, uint32_t* out, int room) {
    int count = 0;
    while (*text != 0 && count < room) {
        char* end = 0;
        const unsigned long value = strtoul(text, &end, 0);
        if (end == text) { ++text; continue; }
        out[count++] = (uint32_t)value;
        text = end;
    }
    return count;
}

static MOD_UNUSED void shader_make_from_tokens(const char* name, const char* text, int pixel) {
    enum { kMostTokens = 512 };
    static uint32_t tokens[kMostTokens];
    const int count = shader_tokens(text, tokens, kMostTokens);
    if (API->shader == 0 || count <= 0) return;
    if (pixel) shader_remember(name, 1, API->shader->CreatePixel(SELF, tokens, count));
    else shader_remember(name, 0, API->shader->CreateVertex(SELF, g_shader_declaration, tokens, count));
}

/* An empty name puts the fixed pipeline back, which is what the game draws with by default */
static MOD_UNUSED void shader_use(const char* vertex, const char* pixel) {
    if (API->shader == 0) return;
    API->shader->Set(SELF, shader_of(vertex, 0), shader_of(pixel, 1));
}

static MOD_UNUSED void shader_drop(const char* name) {
    int at;
    if (API->shader == 0) return;
    for (at = 0; at < kShaders; ++at) {
        if (g_shader_named[at][0] == 0 || strcmp(g_shader_named[at], name) != 0) continue;
        if (g_shader_is_pixel[at]) API->shader->DeletePixel(SELF, g_shader_id[at]);
        else API->shader->DeleteVertex(SELF, g_shader_id[at]);
        g_shader_named[at][0] = 0;
        g_shader_id[at] = AMOD_INVALID_SHADER;
    }
}

static MOD_UNUSED void shader_constant(int pixel, int first, float x, float y, float z, float w) {
    const float values[4] = { x, y, z, w };
    if (API->shader == 0) return;
    if (pixel) API->shader->SetPixelConstant(SELF, first, values, 1);
    else API->shader->SetVertexConstant(SELF, first, values, 1);
}

/* A shape the sheet builds point by point and draws in one go. The layout is the one the
   declaration above describes, so the basic vertex shader reads it as it stands */
enum { kShapePoints = 300 };

/* The vertex the declaration above describes, in that order. The normal is filled in even
   though the basic shader never reads it: the stream is what it is */
typedef struct ShaderPoint {
    float x, y, z;
    float nx, ny, nz;
    uint32_t colour;
    float u, v;
} ShaderPoint;

static ShaderPoint g_shape[kShapePoints];
static int g_shape_count;

static MOD_UNUSED uint32_t shader_rgba(float r, float g, float b, float a) {
    const float channel[4] = { a, r, g, b };
    uint32_t out = 0;
    int at;
    for (at = 0; at < 4; ++at) {
        int value = (int)(channel[at] * 255.0f + 0.5f);
        if (value < 0) value = 0;
        if (value > 255) value = 255;
        out = (out << 8) | (uint32_t)value;
    }
    return out;
}

static MOD_UNUSED void shape_begin(void) {
    g_shape_count = 0;
}

static MOD_UNUSED void shape_point(float x, float y, float z, float u, float v, uint32_t colour) {
    ShaderPoint* point;
    if (g_shape_count >= kShapePoints) return;
    point = &g_shape[g_shape_count++];
    point->x = x;
    point->y = y;
    point->z = z;
    point->nx = 0.0f;
    point->ny = 0.0f;
    point->nz = 1.0f;
    point->colour = colour;
    point->u = u;
    point->v = v;
}

/* Three points make a triangle, so what is left over from the last three is not drawn */
static MOD_UNUSED void shape_draw(void) {
    if (API->shader == 0 || g_shape_count < 3) return;
    API->shader->DrawTriangles(SELF, g_shape, g_shape_count - g_shape_count % 3,
                               (int)sizeof g_shape[0]);
}

static MOD_UNUSED int shape_points(void) {
    return g_shape_count;
}

/* Where the world matrix and the tint of a draw land. A shader reads them from registers, and
   which registers those are is the shader's own business, so the sheet says it once */
static MOD_UNUSED void shader_registers(int worldViewProjection, int world, int tint) {
    if (API->shader == 0) return;
    API->shader->SetTransformRegisters(SELF, worldViewProjection, world);
    API->shader->SetTintRegister(SELF, tint);
}

/* A world matrix built from a place and a size, which is what a sheet can say */
static MOD_UNUSED void shader_matrix(float* out, float x, float y, float z, float scale) {
    memset(out, 0, sizeof(float) * 16);
    out[0] = scale;
    out[5] = scale;
    out[10] = scale;
    out[12] = x;
    out[13] = y;
    out[14] = z;
    out[15] = 1.0f;
}

static MOD_UNUSED void shader_draw_model(uint32_t model, const char* texture,
                                         float x, float y, float z, float scale) {
    float matrix[16];
    AmodTextureId skin = AMOD_INVALID_TEXTURE;
    if (API->shader == 0) return;
    if (texture != 0 && texture[0] != 0 && API->textures != 0) {
        skin = API->textures->Find(SELF, texture);
        if (skin == AMOD_INVALID_TEXTURE) skin = API->textures->Load(SELF, texture, 0, 1);
    }
    shader_matrix(matrix, x, y, z, scale);
    API->shader->DrawModel(SELF, (AmodModelId)model, matrix, skin);
}

/* Many models at once: the API sorts them so a state is set once for a whole run, which is why
   a batch is worth building instead of drawing one by one */
enum { kShadedDraws = 64 };
static AmodShadedDraw g_shaded[kShadedDraws];
static int g_shaded_count;

static MOD_UNUSED void shaded_begin(void) {
    g_shaded_count = 0;
}

static MOD_UNUSED void shaded_add(uint32_t model, const char* texture, uint32_t tint, int blend,
                                  float x, float y, float z, float scale) {
    AmodShadedDraw* draw;
    if (g_shaded_count >= kShadedDraws) return;
    draw = &g_shaded[g_shaded_count++];
    memset(draw, 0, sizeof *draw);
    draw->structSize = sizeof *draw;
    draw->model = (AmodModelId)model;
    draw->tint = tint;
    draw->blend = blend;
    if (texture != 0 && texture[0] != 0 && API->textures != 0) {
        draw->texture = API->textures->Find(SELF, texture);
        if (draw->texture == AMOD_INVALID_TEXTURE)
            draw->texture = API->textures->Load(SELF, texture, 0, 1);
    }
    shader_matrix(draw->matrix, x, y, z, scale);
}

static MOD_UNUSED void shaded_draw(void) {
    if (API->shader != 0 && g_shaded_count > 0)
        API->shader->DrawModels(SELF, g_shaded, g_shaded_count);
}

/* A list of a sheet is a plain array, so a call that wants a matrix or a row of vertices takes
   it as it stands. What the helpers add is the one thing a sheet cannot say: how long it is */
static MOD_UNUSED void shader_model_matrix(uint32_t model, const float* matrix, int length,
                                           const char* texture) {
    AmodTextureId skin = AMOD_INVALID_TEXTURE;
    if (API->shader == 0 || matrix == 0 || length < 16) return;
    if (texture != 0 && texture[0] != 0 && API->textures != 0) {
        skin = API->textures->Find(SELF, texture);
        if (skin == AMOD_INVALID_TEXTURE) skin = API->textures->Load(SELF, texture, 0, 1);
    }
    API->shader->DrawModel(SELF, (AmodModelId)model, matrix, skin);
}

static MOD_UNUSED void shader_constants(int pixel, int first, const float* values, int length,
                                        int fours) {
    if (API->shader == 0 || values == 0 || fours < 1) return;
    if (fours * 4 > length) fours = length / 4;
    if (fours < 1) return;
    if (pixel) API->shader->SetPixelConstant(SELF, first, values, fours);
    else API->shader->SetVertexConstant(SELF, first, values, fours);
}

/* Nine numbers a vertex: place, colour from 0 to 1, and the texture corner. They are laid out
   into what the stream wants, because a sheet has no place to keep a packed colour */
static MOD_UNUSED void shader_triangles(const float* list, int length, int vertices) {
    enum { kNumbersPerVertex = 9 };
    int at;
    if (API->shader == 0 || list == 0 || vertices < 3) return;
    if (vertices * kNumbersPerVertex > length) vertices = length / kNumbersPerVertex;
    vertices -= vertices % 3;
    if (vertices < 3) return;

    shape_begin();
    for (at = 0; at < vertices; ++at) {
        const float* v = list + (size_t)at * kNumbersPerVertex;
        shape_point(v[0], v[1], v[2], v[7], v[8], shader_rgba(v[3], v[4], v[5], v[6]));
    }
    shape_draw();
}
